const cfg = $input.first().json;
const urls = String(cfg.FeedUrls || '').split(',').map(u => u.trim()).filter(Boolean);
if (!urls.length) return [{ json: { url: '' } }];
return urls.map(url => ({ json: { url } }));

const cfg = $('Digest Config').first().json;
const items = $input.all();
const toList = v => String(v || '').toLowerCase().split(',').map(x => x.trim()).filter(Boolean);
const include = toList(cfg.IncludeKeywords);
const exclude = toList(cfg.ExcludeKeywords);
const priority = toList(cfg.PriorityKeywords);
const hours = Number(cfg.LookbackHours) || 24;
const cutoff = Date.now() - hours * 60 * 60 * 1000;
const seen = new Set();
const kept = [];
let tooOld = 0, excluded = 0, notMatched = 0, dupes = 0;
for (const it of items) {
  const j = it.json;
  const title = String(j.title || '').trim();
  const link = String(j.link || '').trim();
  const snippet = String(j.contentSnippet || j.content || '').replace(/<[^>]*>/g, '').trim().slice(0, 300);
  const dateStr = j.isoDate || j.pubDate || '';
  const ts = dateStr ? Date.parse(dateStr) : NaN;
  if (!title && !link) continue;
  if (link && seen.has(link)) { dupes++; continue; }
  if (link) seen.add(link);
  if (!isNaN(ts) && ts < cutoff) { tooOld++; continue; }
  const hay = (title + ' ' + snippet).toLowerCase();
  if (exclude.length && exclude.some(k => hay.includes(k))) { excluded++; continue; }
  if (include.length && !include.some(k => hay.includes(k))) { notMatched++; continue; }
  const isPriority = priority.length ? priority.some(k => hay.includes(k)) : false;
  kept.push({ title, link, snippet, date: dateStr, isPriority });
}
const fmt = arr => arr.map(i => 'Title: ' + i.title + '\nDate: ' + i.date + '\nLink: ' + i.link + '\nSummary: ' + i.snippet).join('\n\n---\n\n');
const priorityItems = kept.filter(i => i.isPriority);
const standardItems = kept.filter(i => !i.isPriority);
return [{ json: { itemCount: kept.length, priorityCount: priorityItems.length, priorityText: priorityItems.length ? fmt(priorityItems) : 'None flagged.', standardText: standardItems.length ? fmt(standardItems) : 'None.', stats: items.length + ' fetched, ' + kept.length + ' kept (' + dupes + ' duplicates, ' + tooOld + ' outside the ' + hours + 'h window, ' + excluded + ' excluded by keyword, ' + notMatched + ' did not match include keywords)' } }];
